:root {
  --paper: #fffdf7;
  --ink: #243238;
  --accent: #ed6a5a;
}

.route-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
}

.pass-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 2px dashed var(--ink);
}

.mark {
  color: var(--accent);
  font-size: 22px;
  line-height: 1;
}

.status {
  border-radius: 999px;
  background: var(--accent);
  color: var(--paper);
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.route-body {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px;
}

.eyebrow,
.location {
  margin: 0;
  color: var(--ink);
  font-size: 12px;
  line-height: 1.35;
}

.eyebrow {
  font-weight: 800;
  letter-spacing: 0.06em;
}

.route-body h1 {
  margin: 3px 0;
  color: var(--ink);
  font-size: 21px;
  line-height: 1.15;
}

.join-button {
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  padding: 7px 12px;
  font-size: 14px;
  font-weight: 800;
}
